import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider } from './auth/AuthContext';
import RequireAuth from './auth/RequireAuth';

// Layout & Styling
import AppLayout from "./components/layout/AppLayout"; // New Modern Layout
import './App.css'; // Keep this for now, but Tailwind is the future!

// Auth Pages
import Login from './pages/auth/Login';
import Signup from "./pages/auth/Signup";

// Feature Pages
import Dashboard from './pages/dashboard/Dashboard';
import ComplaintsPage from './pages/complaints/ComplaintsPage';
import WorkerServicesPage from "./pages/workerServices/WorkerServicesPage";
import MaintenancePage from "./pages/maintenance/MaintenancePage";
import ReceiptPage from "./pages/payments/ReceiptPage";
import GateManagementPage from "./pages/gate/GateManagementPage";
import MyParcelsPage from "./pages/gate/MyParcelsPage";
import MarketplacePage from "./pages/marketplace/MarketplacePage";
import MarketplaceReceiptPage from "./pages/marketplace/MarketplaceReceiptPage";
import MarketplaceSellersAdminPage from "./pages/marketplace/MarketplaceSellersAdminPage";
import MyEvents from "./pages/events/MyEvents";
import FacilityDetails from "./pages/facilities/FacilityDetails";
import AdminFacilities from "./pages/admin/AdminFacilities";
import NoticesPage from "./pages/notices/NoticesPage";
import EventsPage from "./pages/events/EventsPage";
import FacilitiesPage from "./pages/facilities/FacilitiesPage";
import FacilityBookingsPage from "./pages/facilities/FacilityBookingsPage";
import AdminRefunds from "./pages/admin/AdminRefunds";

function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <Routes>
          {/* Public Routes - No Layout Needed */}
          <Route path="/login" element={<Login />} />
          <Route path="/signup" element={<Signup />} />
          <Route path="/" element={<Navigate to="/dashboard" replace />} />

          {/* Protected Routes - All wrapped in AppLayout */}
          <Route path="/dashboard" element={<RequireAuth><AppLayout><Dashboard /></AppLayout></RequireAuth>} />
          <Route path="/complaints" element={<RequireAuth><AppLayout><ComplaintsPage /></AppLayout></RequireAuth>} />
          <Route path="/worker-services" element={<RequireAuth><AppLayout><WorkerServicesPage /></AppLayout></RequireAuth>} />
          <Route path="/notices" element={<RequireAuth><AppLayout><NoticesPage /></AppLayout></RequireAuth>} />
          <Route path="/events" element={<RequireAuth><AppLayout><EventsPage /></AppLayout></RequireAuth>} />

          {/* Events & Facilities */}
          <Route path="/my-events" element={<RequireAuth><AppLayout><MyEvents /></AppLayout></RequireAuth>} />
          <Route path="/facilities" element={<RequireAuth><AppLayout><FacilitiesPage /></AppLayout></RequireAuth>} />

          {/* Booking Routes */}
          <Route path="/facilities/bookings" element={<RequireAuth><AppLayout><FacilityBookingsPage /></AppLayout></RequireAuth>} />
          <Route path="/facilities/my-bookings" element={<RequireAuth><AppLayout><FacilityBookingsPage /></AppLayout></RequireAuth>} />
          <Route path="/facilities/:id" element={<RequireAuth><AppLayout><FacilityDetails /></AppLayout></RequireAuth>} />

          {/* Admin Specific Routes */}
          <Route path="/admin/facilities" element={<RequireAuth><AppLayout><AdminFacilities /></AppLayout></RequireAuth>} />
          <Route path="/admin/refunds" element={<RequireAuth><AppLayout><AdminRefunds /></AppLayout></RequireAuth>} />

          <Route path="/maintenance" element={<RequireAuth><AppLayout><MaintenancePage /></AppLayout></RequireAuth>} />
          <Route path="/gate" element={<RequireAuth><AppLayout><GateManagementPage /></AppLayout></RequireAuth>} />
          <Route path="/my-parcels" element={<RequireAuth><AppLayout><MyParcelsPage /></AppLayout></RequireAuth>} />
          <Route path="/marketplace" element={<RequireAuth><AppLayout><MarketplacePage /></AppLayout></RequireAuth>} />
          <Route path="/marketplace/sellers" element={<RequireAuth><AppLayout><MarketplaceSellersAdminPage /></AppLayout></RequireAuth>} />

          {/* Receipt Pages */}
          <Route path="/payments/:id/receipt" element={<RequireAuth><AppLayout><ReceiptPage /></AppLayout></RequireAuth>} />
          <Route path="/marketplace/payments/:id/receipt" element={<RequireAuth><AppLayout><MarketplaceReceiptPage /></AppLayout></RequireAuth>} />

          {/* Catch-all */}
          <Route path="*" element={<Navigate to="/dashboard" replace />} />
        </Routes>
      </AuthProvider>
    </BrowserRouter>
  );
}

export default App;
